TP.register({id:"lp9-g2",lp:9,grade:"2",mode:"baseline",nextGrade:"3rd grade",build(E){const F=E.F;const PORTAGE="Dalia had carried the canoe twice already. The trail to the second lake was long. It was longer than it had looked on the map. The canoe rode upside down on her shoulders. It sat there like a heavy wooden hat. Halfway along she set it down in the ferns. She sat on a rock to catch her breath. Then her cousin Omar came back down the trail. He took hold of the front end and lifted. With two of them under it, the canoe felt like a different boat. They walked the rest of the portage together. They slid it into the water without stopping once.";const LAYERS="On a hot afternoon the top of a lake feels warm. It can feel like bath water. Your feet hang a little deeper down. They are cold. The sun only heats the first few feet of water. Warm water is lighter than cold water. So it floats and stays on top instead of mixing in. Wind stirs that top layer and spreads the warmth sideways. But the stirring does not reach very far down. In a deep lake the water near the floor can stay cold all summer long.";const WELL="The camp gets its drinking water from a well, not from the lake. A crew drilled down through sand and clay until they reached a layer of water sitting in the gaps between stones. A pump pulls that water up a pipe to a tank on the hill behind the kitchen. From there gravity carries it down to every tap, so nothing has to push it once the tank is full. The water is tested twice each summer.";const WORDS=["paddled","sight","perch","breeze","trout","knot","campsite","refill","slowly","would","snimp","flurk"];const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const passage=(title,text)=>`<h3 style="margin:14px 0 4px;color:var(--sea)">${title}</h3><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${text}</p>`;const pills=(...w)=>`<div class="row center" style="margin-top:18px;gap:18px">${w.map(x=>`<span class="pill" style="font-size:1.4rem">${x}</span>`).join("")}</div>`;const WRITE_DIR="Write on your paper. When you finish, hold it up or read it to your teacher.";const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>{const eye=(x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`;const blush=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`;const smile=(x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`;return eye(cx-sp,cy)+eye(cx+sp,cy)+blush(cx-sp-7,cy+9)+blush(cx+sp+7,cy+9)+smile(cx,cy+9,mw||4)});const n1=v=>Math.round(v*10)/10;const INK="#6B4A3C",LOGC="#C9875A",LOGEND="#E0B07A",LOGLN="#A8724E",DOCK_D="#C08A5E",SHP_A="#8CC79A",SHP_B="#A8D8E8",SHP_C="#F6C97A",SHP_D="#E8A9B8",SHP_E="#E08A2E";function logShape(x,y,w,rot){const k=w/58;return`<g transform="translate(${n1(x)} ${n1(y)}) rotate(${rot||0}) scale(${n1(k)})"><rect x="-26" y="-9" width="52" height="18" rx="9" fill="${LOGC}" stroke="${INK}" stroke-width="3"/><ellipse cx="-26" cy="0" rx="5.5" ry="9" fill="${LOGEND}" stroke="${INK}" stroke-width="2.6"/><path d="M4 -4 h15 M2 4 h12" fill="none" stroke="${LOGLN}" stroke-width="2.4" stroke-linecap="round"/></g>`}const logSvg=w=>`<svg viewBox="0 0 ${w} ${Math.round(w*.46)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a cut log">${logShape(w*.5,w*.23,w*.92)}</svg>`;const LOG=F.table(["Day","Logs split","Weather"],[["Monday","26","clear"],["Tuesday","34","windy"],["Wednesday","19","rain"],["Thursday","31","clear"]],{caption:"Wood Crew Log"});const CLOCKS=[["A",6,10],["B",9,35],["C",4,50],["D",12,25]];function clockRow(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">`+CLOCKS.map(c=>`<div>${F.clock(c[1],c[2],210)}<p class="fig-label">Clock ${c[0]}</p></div>`).join("")+`</div>`}function shapesFig(){const st=`stroke="${INK}" stroke-width="3.6" stroke-linejoin="round"`;const W=980,H=240;let b=`<rect x="3" y="3" width="${W-6}" height="${H-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const num=(x,t)=>`<text x="${x}" y="218" font-size="26" font-weight="700" text-anchor="middle" fill="var(--muted)">${t}</text>`;b+=`<polygon points="100,42 160,150 40,150" fill="${SHP_A}" ${st}/>`+num(100,"1");b+=`<polygon points="268,42 356,42 390,150 234,150" fill="${SHP_B}" ${st}/>`+num(312,"2");b+=`<polygon points="520,36 582,82 558,154 482,154 458,82" fill="${SHP_C}" ${st}/>`+num(520,"3");b+=`<polygon points="716,36 762,36 786,96 762,156 716,156 692,96" fill="${SHP_D}" ${st}/>`+num(739,"4");b+=`<polygon points="880,74 930,46 980,74 980,132 930,160 880,132" fill="${SHP_E}" ${st}/><path d="M880 74 L930 102 L980 74 M930 102 V160" fill="none" ${st}/>`+num(930,"5");return`<svg viewBox="0 0 ${W} ${H}" width="940" role="img" aria-label="Five shapes in a row: a triangle, a four sided shape, a five sided shape, a six sided shape, and a cube drawn so three of its faces show.">${b}</svg>`}function pegRuler(){return F.ruler({length:8,unit:"inches",item:5,itemLabel:"tent peg",px:70})}const STOPS=[{id:1,title:"Camp Word Flip",short:"Camp Words",parts:[{std:["RF.2.3"],kind:"words",words:WORDS,n:12,dur:80,dir:"Read each word out loud. The last two are made-up words. Just sound them out.",desc:"reading words with silent letters, vowel teams, r-controlled vowels, two syllables, a prefix, a suffix, and an irregular spelling",key:["Read each word in order. snimp and flurk are made-up words: listen for the short i before mp, and for the ur sound.","Watch for: the -ed ending said as /d/ (paddled), igh (sight), r-controlled er plus the ch digraph (perch), a blend with the ee team and a final e (breeze), the ou diphthong (trout), silent k (knot), a compound word whose second part has a final e (campsite), the prefix re- (refill), the ow team plus the suffix -ly (slowly), an irregular spelling (would)."]}]},{id:2,title:"The Long Portage",short:"Portage",parts:[{title:"Read the Story",std:["RF.2.4"],kind:"read",n:101,label:"words read correctly",dur:80,dir:"Read the story out loud. Use your best reading voice.",desc:"a 101-word grade-level story read aloud",html:()=>`<p class="small" style="text-align:center">A portage is one part of a trip. You carry the canoe overland from one lake to the next.</p><p class="passage g2-flu">${PORTAGE}</p>`,key:["101 words. Mark each missed word and each self-correction on the passage in the record sheet.","Tell the student what a portage is before the reading starts. The word is explained on the screen too.","Note pace and expression in your notes."]},{title:"Story Questions",std:["RL.2.1"],n:5,dur:60,dir:"Your teacher can read the story again if you need it. Then answer each question out loud.",desc:"asking and answering who, what, why, and how questions about key details in a story",html:()=>`<details class="look-back g2-story" open style="margin-bottom:10px"><summary>The Long Portage (click to open or close the story)</summary><p class="passage" style="font-size:1.45rem;line-height:1.65;max-width:none">${PORTAGE}</p></details>`,after:view=>{const d=view.querySelector("details.g2-story");if(d&&view.querySelector(".g2-flu"))d.open=false},qs:["Who was carrying the canoe at the start of the story?","What did the canoe feel like on her shoulders?","Why did she set the canoe down halfway along the trail?","How did Omar help her?","Your turn. Ask a question about the story. Start with who, what, where, when, why, or how."],key:["Dalia, by herself. She had already carried it twice.","A heavy wooden hat, riding upside down on her shoulders.","She needed to catch her breath. The canoe was heavy and the trail was longer than it had looked on the map.","He came back down the trail, took hold of the front end, and lifted, so the two of them carried it together.","Asks a question that is about this story and starts with a question word (for example: Where were they going? When did they start?)."]},{title:"What It Teaches",std:["RL.2.2"],n:3,dur:45,dir:"Answer out loud. Use the story.",desc:"recounting a story and telling the lesson it teaches",html:()=>`<p class="big" style="margin-top:0">Think about the whole story from start to finish.</p>`,qs:["Retell the story in order, in three or four sentences.","What lesson does this story teach?","Which part of the story shows that lesson best?"],key:["The retelling has the beginning, the middle, and the end in order: Dalia carries the canoe alone, she gets tired and sets it down halfway, Omar comes back and takes the front end, and the two of them finish the portage together.","A hard job gets lighter when someone helps you with it. Any wording of that idea counts, such as: it is easier with a friend, or do not be afraid to let someone help.","The line where the canoe felt like a different boat once two of them were under it. Naming the moment Omar lifted the front end also counts."]}]},{id:3,title:"Camp Problems",short:"Problems",parts:[{std:["2.OA.A.1"],n:5,dur:90,dir:"Read each problem with your teacher. Solve it on your paper. You can draw or write a number sentence. Say your answer.",desc:"one-step addition and subtraction word problems within 100 with the unknown in different places",html:()=>`<p class="big" style="margin-top:0">The wood crew keeps the camp stocked all summer. There is nothing to count on the screen, so work each problem on your paper.</p>`,qs:["The rack held 45 logs. 28 of them went on the fire. How many logs are left on the rack?","Cabin One picked 34 berries and Cabin Two picked 29. How many berries is that in all?","Cabin One has 26 campers. Cabin Two has 18 more campers than Cabin One. How many campers does Cabin Two have?","Some paddles were in the shed. The crew took out 37 of them. Now 16 are left. How many paddles were in the shed at first?","There were 61 water bottles in the crate. The campers took 48 of them. How many are left?"],key:["17 logs (45 - 28 = 17)","63 berries (34 + 29 = 63)","44 campers (26 + 18 = 44)","53 paddles (a box take away 37 is 16, or 16 + 37 = 53)","13 bottles (61 - 48 = 13)"]}]},{id:4,title:"Crates, Bundles, and Ones",short:"Place Value",parts:[{std:["2.NBT.A.1"],n:6,dur:75,dir:"Look at the blocks. Answer out loud.",desc:"three-digit place value, including a hundred as ten tens",html:()=>`<p class="big" style="margin-top:0">The crew stacks logs like this. A flat is a crate of 100. A long block is a bundle of 10. A small cube is one loose log.</p>`,fig:()=>F.row(F.blocks(3,5,2)),qs:["Look at the picture. How many hundreds, tens, and ones are there? What number is that?","A crate holds 100 logs. How many bundles of ten does it take to fill one crate?","In the number 629, what does the 6 stand for?","In the number 408, how many tens are there? How many ones?","The crew has 5 crates, 3 bundles, and 7 loose logs. What number is that?","Which is more, 3 crates of a hundred or 30 bundles of ten? How do you know?"],key:["3 hundreds, 5 tens, and 2 ones. That is 352","10 bundles. A hundred is the same as ten tens","6 hundreds, which is 600","0 tens and 8 ones. The 0 is holding the tens place","537","They are the same. 3 hundreds is 300, and 30 tens is also 300"]}]},{id:5,title:"Warm on Top, Cold Below",short:"Layers",parts:[{std:["RI.2.1"],n:5,dur:60,dir:"Read about lake water. Then answer each question out loud.",desc:"asking and answering what, where, why, and how questions about an informational text the student read",html:()=>passage("Warm on Top, Cold Below",LAYERS),qs:["What heats the water at the top of a lake?","Why does the warm water stay on top instead of mixing in?","What does the wind do to the top layer?","Where in a lake can the water stay cold all summer?","Your turn. Ask a question about lakes. Start with who, what, where, when, why, or how."],key:["The sun does, and only down through the first few feet","Because warm water weighs less than the cold water under it, so it rides on top instead of sinking in","It mixes the warm layer sideways across the lake, but that mixing never gets down deep","Near the floor of a deep lake","Asks a question that is about the topic and starts with a question word (for example: How deep is the warm layer? Why is warm water lighter?)."]}]},{id:6,title:"Fix the Camp Note",short:"Camp Note",parts:[{title:"Say It Right",std:["L.2.1"],n:6,dur:65,dir:"Say each answer out loud.",desc:"spoken grammar items (irregular past tense, irregular plural, reflexive pronoun, adverb, word order, joining two sentences)",qs:["Today we swim at the dock. Yesterday we ____.","One goose, two ____.","We carried the canoe all by ____.","Which word fits? The wind moved ____ through the pines. Is it gentle or gently?","Mix-up! Put these words in order to make a sentence: <b>glided / the canoe / across the lake</b>","Join these two sentences with the word <b>because</b>: We stopped at noon. The sun was too hot."],key:["swam","geese","ourselves","gently","The canoe glided across the lake.","We stopped at noon because the sun was too hot."]},{title:"Write It Right",std:["L.2.2"],n:6,dur:65,dir:"Write each answer on your paper and hold it up.",desc:"written conventions (capital letters in place names, an apostrophe for a possessive and a contraction, a comma in a letter greeting, spelling two patterns)",qs:["Fix this sentence: <b>we paddled up pine creek to loon lake</b>","The paddle belongs to the crew. Write the missing word: <b>the ____ paddle</b>","This is the start of a letter. Write it and add the missing mark: <b>Dear Dalia</b>","Write <b>did not</b> as one short word with an apostrophe.","Listen. Write the word your teacher says.","Listen. Write the second word your teacher says."],key:["We paddled up Pine Creek to Loon Lake. (capital W to start, capital P and capital C in the creek name, capital L and capital L in the lake name, and a period)","crew’s (apostrophe before the s)","Dear Dalia, (comma after Dalia)","didn’t (apostrophe where the o of not comes out)","Say: “Bright. The morning was bright and cool.” The student writes bright (igh).","Say: “Paddle. We left the paddle on the dock.” The student writes paddle (two syllables, -le at the end)."]}]},{id:7,title:"Count Along the Shore",short:"Skip Count",parts:[{std:["2.NBT.A.2"],n:5,dur:70,dir:"Count out loud.",desc:"counting within 1000 and skip-counting by 5s, 10s, and 100s",html:()=>`<p class="big" style="margin-top:0">The crew drives a trail stake every 5 steps along the shore path, so the counting goes 5, 10, 15, and on.</p>`,qs:["Skip count by 5s from 70 to 110.","Skip count by 10s from 440 to 510.","Count by ones from 795 to 804.","Skip count by 100s from 260 to 860.","Count back by 10s from 530 to 470."],key:["70, 75, 80, 85, 90, 95, 100, 105, 110. Watch the jump past 95.","440, 450, 460, 470, 480, 490, 500, 510. Watch the jump past 490.","795, 796, 797, 798, 799, 800, 801, 802, 803, 804. Watch the jump past 799.","260, 360, 460, 560, 660, 760, 860","530, 520, 510, 500, 490, 480, 470. Watch the step back past 500."]}]},{id:8,title:"Three Ways to Write It",short:"Three Ways",parts:[{std:["2.NBT.A.3"],n:6,dur:75,dir:"Say the first two answers out loud. Write the rest on your paper and hold it up.",desc:"reading and writing numbers to 1000 as numerals, number names, and expanded form",html:()=>`<p class="big" style="margin-top:0">The crew writes the log count three different ways in the camp logbook.</p>`,qs:["Read this number out loud: 713.","What number is 500 + 40 + 9?","Write 806 using words.","Write <b>four hundred seventy-one</b> as a numeral.","Write 358 in expanded form.","Write 60 + 900 + 2 as one number."],key:["seven hundred thirteen","549","eight hundred six (no tens, so no ten word goes in)","471","300 + 50 + 8","962 (the parts are out of order on purpose: 900 + 60 + 2)"]}]},{id:9,title:"Logbook Math",short:"Logbook",parts:[{std:["2.NBT.B.7"],n:4,dur:100,dir:"Solve each one on your paper. Show your work and hold it up. Say your answer.",desc:"adding and subtracting within 1000 with a place value strategy and relating it to a written method",html:()=>`<p class="big" style="margin-top:0">Every summer the crew writes down how many logs the whole camp used.</p>`,qs:["Last summer the camp used 346 logs at the fire ring and 275 at the cook stove. How many in all? Show how you added.","The camp wants 700 logs split before the season starts. So far 268 are split. How many more are needed?","The crew split 489 logs in June and 157 more in July. How many did they split in all?","There were 823 logs in the shed. The crew carried out 476 of them. How many are still in the shed?"],key:["621 logs (346 + 275 = 621). Listen for hundreds with hundreds, tens with tens, ones with ones, and for making a new ten and a new hundred.","432 more (700 - 268 = 432). This one needs two decomposes, so watch the work.","646 logs (489 + 157 = 646). A new ten and a new hundred are both made here.","347 logs (823 - 476 = 347). Two decomposes again."]}]},{id:10,title:"Clock and Camp Store",short:"Clock",parts:[{title:"Read the Clock",std:["2.MD.C.7"],n:5,dur:80,dir:"Look at each clock. Say the time out loud. Write the last answer on your paper.",desc:"telling time on an analog clock to the nearest five minutes and using a.m. and p.m.",html:()=>`<p class="big" style="margin-top:0">The clock in the camp kitchen keeps everyone on time.</p>`,fig:()=>clockRow(),key:["Clock A: 6:10, said as six ten or ten past six. The minute hand is on the 2, and each number mark is five minutes.","Clock B: 9:35, said as nine thirty-five or twenty-five to ten. The minute hand is on the 7. Watch for a student who says ten thirty-five because the hour hand has moved past halfway.","Clock C: 4:50, said as four fifty or ten to five. The minute hand is on the 10. The hour hand is almost on the 5, so watch for a student who says five fifty.","Clock D: 12:25, said as twelve twenty-five. The minute hand is on the 5.","Say: The canoes go out at 2:15 in the afternoon. Write that time with a.m. or p.m. (2:15 p.m., because the afternoon is after noon.)"]},{title:"Camp Store",std:["2.MD.C.8"],n:5,dur:70,dir:"Look at the coins. Say the first answers out loud. Write number 3 on your paper.",desc:"solving money problems with quarters, dimes, nickels, and pennies and writing amounts with the cent and dollar symbols",fig:()=>F.row(F.coins(["Q","Q","D","N","P"])),qs:["How much money is on the screen?","A trail map at the camp store costs 40 cents. You pay with 2 quarters. How much change do you get?","Write eighty-five cents two ways, once with a cent sign and once with a dollar sign.","Show 35 cents with the fewest coins you can. Which coins would you use?","You have 3 dimes and 4 nickels. How much money is that?"],key:["66 cents (25 + 25 + 10 + 5 + 1 = 66)","10 cents (2 quarters is 50 cents, and 50 - 40 = 10)","85¢ and $0.85. The dollar form needs the point and two places after it.","2 coins: one quarter and one dime (25 + 10 = 35)","50 cents (3 dimes is 30, 4 nickels is 20, and 30 + 20 = 50)"]}]},{id:11,title:"Measure and Shapes",short:"Measure",parts:[{title:"Measure the Peg",std:["2.MD.A.1"],n:6,dur:95,dir:"Look at the tent peg above the ruler. Answer out loud. For the last one, get a real ruler and measure.",mats:["a ruler"],desc:"measuring length with a ruler marked in inches, choosing a measuring tool that fits the job, and measuring a real object with a ruler",fig:()=>F.row(pegRuler()),qs:["How long is the tent peg?","Where do you line up the end of the peg before you read the ruler?","If you lined the peg up at the 1 instead of the 0, would your answer be too big or too small?","Is an inch ruler or a yardstick the better tool for this peg? Why?","Name a tool you would use to measure how long the dock is, and tell why.","Now get a real ruler. Pick up a pencil or a spoon and measure it. How long is it?"],key:["5 inches. The peg starts at 0 and ends at the 5 mark.","At the 0 mark on the ruler, not at the very edge of the plastic.","Too small. Starting at 1 cuts one inch off the measurement, so the peg would read 4 inches.","The inch ruler. The peg is shorter than a foot, so a yardstick would be clumsy and the peg would not even reach the first foot mark.","A measuring tape or a yardstick, because the dock is many feet long and a ruler would have to be moved over and over.","Picks up the ruler, lines one end of the object up with the 0, reads the nearest whole inch or centimeter, and says the unit."]},{title:"Camp Shapes",std:["2.G.A.1"],n:5,dur:60,dir:"Look at the five shapes. Answer out loud.",desc:"naming shapes by their number of sides, angles, and faces",fig:()=>F.row(shapesFig()),qs:["Name shape 1. How many sides does it have? How many angles?","Shape 2 has 4 sides. What is the name for any shape with 4 sides?","Name shape 3.","Name shape 4.","Shape 5 is a cube. How many faces does a cube have?"],key:["A triangle. 3 sides and 3 angles.","A quadrilateral. This one is a trapezoid, and trapezoid is a fine answer too.","A pentagon. It has 5 sides and 5 angles.","A hexagon. It has 6 sides and 6 angles.","6 faces. Only 3 of them show in a drawing like this one."]}]},{id:12,title:"Fish from the Dock",short:"Graph",parts:[{std:["2.MD.D.10"],n:5,dur:70,dir:"Look at the graph. Answer out loud.",desc:"reading a bar graph with four categories and solving put-together, take-apart, and compare problems from it",html:()=>`<p class="big" style="margin-top:0">The campers counted the fish they could see from the end of the dock each morning.</p>`,fig:()=>F.row(F.barGraph({title:"Fish seen from the dock",cats:["Mon","Tue","Wed","Thu"],vals:[8,5,11,6],max:12,step:1})),qs:["How many fish were seen on Wednesday?","Which morning had the fewest fish?","How many more fish on Wednesday than on Tuesday?","How many fish on Monday and Thursday together?","How many fish were seen on all four mornings?"],key:["11","Tuesday, with 5","6 more (11 - 5 = 6)","14 (8 + 6 = 14)","30 (8 + 5 + 11 + 6 = 30)"]}]},{id:13,title:"Even Teams",short:"Even Odd",parts:[{title:"Odd or Even",std:["2.OA.C.3"],n:5,dur:55,dir:"Answer out loud. Tell how you know.",desc:"telling odd from even numbers and writing an even number as two equal addends",html:()=>`<p class="big" style="margin-top:0">Every camper needs a canoe partner, so the crew checks whether a group splits in two.</p>`,fig:()=>F.row(F.array(2,7,"dot")),qs:["Count the dots in the picture. Is that number even or odd? How do you know?","Is 9 even or odd? How do you know?","The camp has 18 paddles. Can every paddle have a partner?","Write an equation that shows 16 as two equal addends.","Name an odd number between 20 and 30."],key:["14, and it is even. The dots make 2 equal rows of 7, so the group splits in half with none left over.","Odd. 9 makes 4 pairs with 1 left over, and it cannot split into two equal groups.","Yes. 18 is even, so it makes 9 pairs with none left over.","8 + 8 = 16","21, 23, 25, 27, or 29"]},{title:"Rows of Logs",std:["2.OA.C.4"],n:5,dur:55,dir:"Look at the rows. Answer out loud. Write the addition sentences on your paper.",desc:"finding the total in a rectangular array by adding equal addends",fig:()=>F.row(F.array(4,5,"dot")),qs:["How many rows are there? How many dots in each row?","Write an addition sentence with equal addends that matches the picture.","How many dots are there in all?","A different stack has 3 rows of 6. Write the addition sentence and the total.","Two tents each hold 5 cots. Write the addition sentence and the total."],key:["4 rows, with 5 in each row","5 + 5 + 5 + 5 = 20. One addend for each row.","20","6 + 6 + 6 = 18","5 + 5 = 10"]}]},{id:14,title:"Camp Radio",short:"Report",parts:[{title:"Listen Up",std:["SL.2.2"],n:4,dur:50,read:WELL,dir:"Listen first. Then answer your teacher's questions out loud.",desc:"recounting and describing key ideas and details from a text read aloud",html:()=>`<p class="huge" aria-hidden="true">${ic("ear",96)}</p><p class="big" style="text-align:center">Listen carefully. Your teacher will read a report about where the camp gets its water.</p>`,key:["Ask: Where does the camp's drinking water come from? (a well, not the lake)","Ask: Describe what the crew had to drill through. (sand and clay, down to a layer of water sitting in the gaps between stones)","Ask: Why does nothing have to push the water once the tank is full? (the tank sits on a hill, so gravity carries the water down to every tap)","Say: Tell me two more things you learned. (any two: a pump pulls the water up a pipe, the tank is behind the kitchen, the water is tested twice each summer)"]},{title:"Tell Me About It",std:["SL.2.4"],n:4,label:"checks met",dur:45,dir:"Tell about it out loud. Say what happened first, next, and last.",desc:"telling about an experience in order, with facts and details, in clear complete sentences",html:()=>`<p class="big">Tell me about a time you carried something heavy, or a time someone helped you finish a job. Where were you? What did you do? How did it end?</p>${pills("First","Next","Last")}`,key:["Tells what happened in an order that makes sense","Gives facts that fit (where, when, who, or what)","Uses describing details (how it looked, felt, or sounded)","Speaks in complete sentences, loud and clear enough to hear"]}]},{id:15,title:"The Crew Log",short:"Crew Log",parts:[{std:["W.2.8"],n:4,dur:65,dir:"Use the log to answer. Say the first two answers out loud. Write number 3 on your paper and hold it up. Then say number 4.",desc:"gathering information from a provided log and recalling information from experience to answer questions",html:()=>`<p class="big" style="margin-top:0">The wood crew writes down how many logs they split each day, and what the weather was like.</p>`,fig:()=>F.row([logSvg(74),"One log"],LOG),qs:["Use the log. Which day did the crew split the most logs?","Which days were clear?","A friend asks, “Did the crew split more logs on Monday or on Thursday?” Write one sentence that answers your friend. Use the log.","Now use what you remember. Think of a job you have done outside. What was it, and what made it easy or hard? Say it in a sentence."],key:["Tuesday, with 34 logs","Monday and Thursday","The sentence says Thursday and uses the numbers from the log (Thursday had 31 and Monday had 26).","Tells one thing remembered from a real job outside, in a sentence that answers the question (for example: I pulled weeds, and it was hard because the ground was dry.)."]}]},{id:16,title:"Camp Journal",short:"Write",parts:[{wk:"opinion",alt:{group:"write",key:"opinion",label:"Best Camp Day",icon:"💬",hint:"Tell what you think and why"},std:["W.2.1"],n:4,label:"checks met",dur:140,dir:WRITE_DIR,desc:"an opinion piece about the best way to spend a day at camp, with reasons and a closing",html:()=>`<p class="big">The camp can plan one more day before everyone goes home. Should it be a day on the water or a day on the trail? Write what you think. Give two reasons. Write 4 sentences.</p><div class="figure">${ic("canoe",64)}${ic("mountain",64)}</div>${pills("I think","One reason","Another reason","That is why")}`,key:["Names the topic and states an opinion: a day on the water or a day on the trail","Gives one reason that supports the opinion","Gives a second reason, or a detail that backs up the first one","Uses a linking word such as because, and, or also, and ends with a closing sentence"]},{wk:"facts",alt:{group:"write",key:"facts",label:"How To Do It",icon:"📖",hint:"Teach a reader about it"},std:["W.2.2"],n:4,label:"checks met",dur:140,dir:WRITE_DIR,desc:"an informative piece that introduces a topic, gives facts, and closes",html:()=>`<p class="big">Pick one thing you know how to do outdoors: set up a tent, build a fire ring, paddle a canoe, or pack a bag for a hike. Write 4 sentences that teach a reader about it.</p><div class="figure">${ic("tent",56)}${ic("fire",56)}${ic("canoe",56)}${ic("pack",56)}</div>${pills("My topic is","One fact","Another fact","Now you know")}`,key:["Introduces the topic in the first sentence","Gives one fact or step about it","Gives a second fact, step, or definition","Ends with a closing sentence that wraps it up"]},{wk:"story",alt:{group:"write",key:"story",label:"A Summer Story",icon:"✏",hint:"Tell it in order"},std:["W.2.3"],n:4,label:"checks met",dur:140,dir:WRITE_DIR,desc:"a short narrative with events in order, details about actions and feelings, time words, and an ending",html:()=>`<p class="big">You are at the lake camp. You walk down to the dock early, before anyone else is awake, and something small and surprising happens. Write a story about it. Tell it in order. Tell what you did and how you felt. Write 4 sentences.</p>${pills("First","Then","After that","In the end")}`,key:["Tells about one event or a short set of events in order","Includes details about actions, thoughts, or feelings","Uses time words like first, then, after that, or in the end","Ends with a sentence that wraps up the story"]}]},{id:17,title:"Three Pots at the Camp Kitchen Window",short:"Plant Test",parts:[{std:["2-LS2-1"],n:3,dur:90,dir:"Read the chart. Then answer out loud.",desc:"reading the results of a plant test and planning a fair test of one thing a plant needs",html:()=>`<p class="big">The camp grows beans in pots so there is something fresh to eat. Three pots were planted on the first day of camp and measured two weeks later.</p>
     <table class="bigTable"><tr><th>Pot</th><th>What it got</th><th>After two weeks</th></tr>
     <tr><td>1</td><td>sun on the kitchen window ledge, watered</td><td>22 centimeters, broad green leaves</td></tr>
     <tr><td>2</td><td>sun on the kitchen window ledge, not watered</td><td>5 centimeters, then the stem went brittle</td></tr>
     <tr><td>3</td><td>in the cool store room, watered</td><td>15 centimeters, thin and almost white</td></tr></table>
     <div class="figure">${ic("sprout",88)}${ic("sun",88)}</div>`,qs:["Which pot did best, and what did it get?","Pot 3 is taller than pot 2 and still in trouble. Say what pot 3 was missing and what that did to it.","You want to test only whether a bean needs sunlight. Name two things you would keep the same, and name the one thing you would change."],key:["Pot 1, 22 centimeters with broad green leaves. It got both sunlight and water.","Pot 3 was missing sunlight. It used the food stored in the bean to stretch upwards looking for light, so it is tall but thin and almost white, and it cannot make more food.","Keep the same: the same beans, the same pot, the same soil, the same watering. Change only one thing: one pot in the sun and one pot in the store room. Changing two things is not a fair test, so ask again."]},{std:["2-LS2-2"],n:2,dur:90,dir:"Draw your model on your paper. Then tell your teacher about it.",desc:"making a simple model that does the job an animal does when it moves seeds",html:()=>`<p class="big">Ducks swim in one weedy bay. Then they land in another. Tiny water plant seeds stick to the mud. The mud is on their feet. The seeds ride along. Some of them start growing in the new bay.</p>
     <div class="figure">${ic("duck",88)}${ic("wave",88)}</div>
     <p class="big">Draw a model you could really build out of camp things, such as a sponge tied under a stick or a flat paddle with grooves, that would pick up muddy seeds in one place and set them down in another.</p>`,qs:["Draw your model. Label the part that holds the mud and the seeds, and show how it comes off again.","Which animal job does your model copy, and why is it useful to a plant that its seeds get carried across water?"],key:["Any model with a part that mud sticks to and a way to let it go: a sponge under a stick, a grooved paddle, a cloth pad that can be rinsed. The two labeled parts are what to look for.","It copies a duck carrying muddy seeds on its feet from bay to bay. A water plant cannot walk, so without an animal carrying them its seeds would all stay in the same bay and crowd each other out."]}]},{id:18,title:"The Shallow Shore and the Pine Ridge",short:"Two Places",parts:[{std:["2-LS4-1"],n:3,dur:90,dir:"Read both lists. Answer out loud.",desc:"comparing the kinds of living things found in two different habitats",html:()=>`<p class="big">Campers spent half an hour in each of two places and wrote down every kind of living thing they found.</p>
     <table class="bigTable"><tr><th>The shallow lake shore</th><th>The dry pine ridge</th></tr>
     <tr><td>3 kinds of water weed</td><td>2 kinds of pine</td></tr>
     <tr><td>2 kinds of small fish</td><td>1 kind of dry moss</td></tr>
     <tr><td>1 frog, 2 kinds of dragonfly</td><td>1 chipmunk, 1 kind of beetle</td></tr>
     <tr><td>1 heron, 1 kind of water snail</td><td>2 kinds of bird</td></tr></table>
     <div class="figure">${ic("fish",80)}${ic("pine",80)}</div>`,qs:["How many kinds of living things are on each list?","Name one living thing from the shore that could not live on the ridge, and say why.","The shore and the ridge are a five minute walk apart. Why are the lists so different?"],key:["The shore has 10. Three water weeds, two fish, one frog, two dragonflies, one heron and one water snail. The ridge has 7. Two pines, one moss, one chipmunk, one beetle and two birds.","Any sensible pick with a reason: a fish needs water to breathe and swim in, a water snail needs water, a water weed needs its roots under water, a dragonfly lays its young in water.","Because one place has water and soft mud and the other is dry sand and needles under trees, and living things live where they can get what they need."]}]},{id:19,title:"One Night, or After the Ice",short:"Fast or Slow",parts:[{std:["2-ESS1-1"],n:3,dur:90,dir:"Read both notes. Answer out loud.",desc:"using two sources as evidence that some Earth events happen quickly and some happen slowly",html:()=>`<p class="big">Two notes about this lake, from two different places.</p>
     <table class="bigTable"><tr><th>Where it came from</th><th>What it says</th></tr>
     <tr><td>the camp log from last summer</td><td>One storm in the night moved the whole sandbar at the river mouth to the other side of the channel.</td></tr>
     <tr><td>a display in the park visitor room</td><td>This lake sits in a hollow that was scooped out by a thick sheet of ice over thousands of years, long before there were people here.</td></tr></table>`,qs:["Which note tells about a change that happened in one night?","Which note tells about a change that took thousands of years?","Name one more change to the land that happens quickly, and one that happens slowly."],key:["The camp log, the sandbar moved across the channel in one night.","The visitor room display, the lake hollow scooped out by ice over thousands of years.","Quick: a flood, a rockfall, a bank falling in, a tree pushed over in a storm. Slow: a river cutting a canyon, a cliff wearing back, a hill wearing down. The answer has to name a change to the land, not just a kind of weather."]},{std:["2-ESS2-3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling where water is found on Earth and whether it is solid or liquid",html:()=>`<p class="big">Nearly everything at this camp is arranged around water.</p>
     <div class="figure">${ic("wave",80)}${ic("drop",80)}${ic("cloud",80)}</div>`,qs:["Name three places around this camp where you would find water.","Most of the water on Earth is in the ocean and it is salty. Is the lake water salty or fresh, and how do you know?","The cooler in the kitchen has ice in it. Is ice solid or liquid? Is the lake solid or liquid in summer?"],key:["Any three: the lake, the stream, the spring by the trail, rain, the clouds, the cooler ice, under the ground, inside the trees.","Fresh. You can tell because the camp drinks it and cooks with it, fish like these live in it, and trees and reeds grow at its edge. Salty water would not do those things.","Ice is solid. The lake in summer is liquid."]}]},{id:20,title:"Holding the Bank, and a Map of the Camp",short:"The Land",parts:[{std:["2-ESS2-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"comparing two things built to stop waves from washing the bank away",html:()=>`<p class="big">Waves from passing boats eat into the bank beside the dock. Two fixes were tried and the bank was measured each year.</p>
     <table class="bigTable"><tr><th>What was along the bank</th><th>Bank lost in one year</th></tr>
     <tr><td>nothing</td><td>40 centimeters</td></tr>
     <tr><td>a row of heavy rocks at the waterline</td><td>3 centimeters</td></tr>
     <tr><td>a crib of logs filled with gravel</td><td>8 centimeters</td></tr></table>`,qs:["Which one held the bank best?","How do you know, using the numbers in the chart?","Rocks have to be hauled in by boat and logs are already on the ridge. When might the camp still build the log crib?"],key:["the row of heavy rocks at the waterline","Only 3 centimeters of bank was lost behind the rocks, 8 centimeters behind the log crib, and 40 centimeters where there was nothing. The reason must come from the numbers.","When they cannot get a boat in with rocks, or when there is no money or time for hauling, and 8 centimeters is much better than 40. Any reason that weighs what it costs against what it saves counts."]},{std:["2-ESS2-2"],n:3,dur:90,dir:"Draw on your paper and hold it up.",desc:"making a model of an area that shows the shapes of the land and the bodies of water in it",html:()=>`<p class="big">Make your own model map of the camp. Put in the pine ridge, the flat clearing where the cabins are, the lake, and the stream that runs into it. Add a key that says which is which.</p>
     <div class="figure">${ic("map",88)}${ic("mountain",88)}${ic("tent",88)}</div>`,qs:["Draw your model map with the ridge, the flat clearing, the lake and the stream on it.","Show me your key. Which parts are land and which parts are water?","Water runs downhill. Looking at your own map, which way does the stream run?"],key:["All four on the page and told apart by shape or color: the ridge as a bump or as rings, the clearing left flat, the lake as a closed shape, the stream as a line reaching it.","Points to each part and reads the key. The key is what makes this a model and not just a picture.","Down off the ridge and into the lake, which is the lowest part of their map. The answer has to match their own drawing, so follow their finger."]}]},{id:21,title:"Sorting the Camp Kit",short:"Materials",parts:[{std:["2-PS1-1"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"describing materials by properties you can see or feel and sorting them into groups",html:()=>`<p class="big">Four things out of the kit box, and what the campers wrote about each one.</p>
     <table class="bigTable"><tr><th>Item</th><th>Material</th><th>What they wrote</th></tr>
     <tr><td>a cook pot</td><td>aluminum metal</td><td>hard, shiny, light for its size, gets hot fast</td></tr>
     <tr><td>a throw line</td><td>nylon</td><td>bends, floats, water runs off it</td></tr>
     <tr><td>a jam jar</td><td>glass</td><td>hard, smooth, you can see through it, heavy</td></tr>
     <tr><td>a kit sack</td><td>canvas</td><td>bends easily, rough, soaks water up slowly</td></tr></table>`,qs:["Sort the four items into a hard group and a group that bends.","Two of them are heavy for their size or light for their size. Which is light and which is heavy?","Name one more property from the chart you could sort these four by, and sort them by it."],key:["Hard: the metal cook pot and the glass jar. Bends: the nylon line and the canvas sack.","The metal cook pot is light for its size. The glass jar is heavy.","Any property that can be seen or felt and that really splits the four: see through or not, floats or sinks, shiny or dull, rough or smooth, soaks water up or sheds it. The groups have to match the property named."]},{std:["2-PS1-2"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"using test data to choose the material that suits a job",html:()=>`<p class="big">The camp needs food bags to carry over the portage trail. Three materials were each loaded with 5 kilograms and carried through one rainy portage.</p>
     <table class="bigTable"><tr><th>Material</th><th>Food dry at the far end</th><th>Bag after the portage</th></tr>
     <tr><td>paper sack</td><td>no</td><td>split down one side</td></tr>
     <tr><td>cotton sack</td><td>no</td><td>whole, but soaked through</td></tr>
     <tr><td>coated nylon sack</td><td>yes</td><td>whole and dry</td></tr></table>`,qs:["Which material should the food bags be made of?","Which two pieces of the chart make you sure?","The cotton sack came through whole. Why is it still a poor choice for food?"],key:["the coated nylon sack","The food was dry at the far end and the bag was still whole and dry. Both columns have to be used, not just one.","It soaked through, so the food inside got wet. Wet bread and wet oats spoil, so a bag that holds together but lets the rain in has still lost the food."]}]},{id:22,title:"Taken Apart, Heated, Cooled",short:"Heat and Cold",parts:[{std:["2-PS1-3"],n:2,dur:75,dir:"Answer out loud. You may draw if it helps.",desc:"telling how a thing built from a few pieces can be taken apart and built into something new",html:()=>`<p class="big">The drying rack is by the dock. It is made of 5 straight poles. They are tied with 6 lashings. A camper untied every lashing. He laid the poles along the dock.</p>
     <div class="figure">${ic("board",88)}${ic("box",88)}</div>`,qs:["The rack is gone. Are the poles and lashings gone too? What is lying on the dock?","Build something new in your head out of those 5 poles and 6 lashings. What is it, and how do the pieces go together?"],key:["No. All 5 poles and all 6 lashings are still there. They are the same pieces, just not tied together as a rack any more.","Any real thing from 5 poles and 6 lashings: a tripod for a pot, a flag pole, a frame for a shelter, a ladder, a gate, a bench. Listen for how the pieces join, because that is the evidence the same set of pieces made something different."]},{std:["2-PS1-4"],n:3,dur:90,dir:"Read the chart. Answer out loud.",desc:"arguing with evidence that some heating and cooling changes can be undone and some cannot",html:()=>`<p class="big">Two things happened at the camp fire grate on the same evening.</p>
     <table class="bigTable"><tr><th>What happened</th></tr>
     <tr><td>A cup of ice from the cooler was set near the fire and became a cup of water.</td></tr>
     <tr><td>A slice of bread was left on the grate too long and turned black and brittle.</td></tr></table>
     <div class="figure">${ic("fire",80)}${ic("bread",80)}</div>`,qs:["Put the cup of water back in the cooler. What happens to it?","Put the black slice back in the cooler. Does it turn back into bread?","Which of the two changes can be undone, and what is your evidence?"],key:["It freezes back into ice, and setting it near the fire again would melt it.","No. It stays black and brittle. Cold does nothing for it.","The ice and water change can be undone. The evidence is that the water freezes again in the cooler and melts again by the fire, while the burnt bread never comes back however cold it gets. Listen for the student using what happened, not just saying yes or no."]}]},{id:23,title:"The Paddles That Slide Off",short:"Solve It",parts:[{std:["K-2-ETS1-1"],n:2,dur:60,dir:"Read the note. Answer out loud.",desc:"naming a problem people want to fix and asking a question about it",html:()=>`<p class="passage">The paddles are laid flat on the dock between trips so they can dry. The dock boards slope a little towards the water. The paddles are smooth. Every day one or two slide off the edge. Someone has to wade in and fetch them out of the shallows.</p>`,qs:["What is the problem the camp wants to fix? Say it in one sentence.","Ask one question that would help you fix it."],key:["The paddles slide off the sloping dock into the water. Naming the sliding, not the wading in, is the problem.","Any real question: how many paddles are there, how long is a paddle, how much does the dock slope, how wide is the dock, is there a rail or a wall to lean them on. A statement is not a question, so ask once more."]},{std:["K-2-ETS1-2"],n:2,dur:75,dir:"Draw on your paper and hold it up.",desc:"drawing a design and telling how its shape does the job",html:()=>`<p class="big">Draw something that would hold the paddles on the dock and still let them dry. Think hard about its shape.</p>
     <div class="figure">${ic("canoe",88)}${ic("board",88)}</div>`,qs:["Draw your fix.","Tell me how the shape of what you drew keeps the paddles from sliding, and how the air still gets at them."],key:["Any design that could really hold a paddle and still let air through: a rack with slots to stand them in, two pegs that each blade rests between, a rail along the low edge, hooks on a post, a frame that holds them on edge.","The shape and the air are both being checked. Something like: the slots hold the handle so it cannot slide and the blade stands up in the air, the pegs stop it moving sideways but nothing covers it, standing them on edge lets the wind get both sides."]},{std:["K-2-ETS1-3"],n:2,dur:60,dir:"Read the chart. Answer out loud.",desc:"comparing test results from two designs built for the same problem",html:()=>`<p class="big">Both fixes were used for a week with 10 paddles.</p>
     <table class="bigTable"><tr><th>Fix</th><th>Paddles that went in the water</th><th>Paddles still damp next morning</th></tr>
     <tr><td>a rack with a slot for each paddle</td><td>0</td><td>0</td></tr>
     <tr><td>a rail along the low edge of the dock</td><td>1</td><td>7</td></tr></table>`,qs:["Which fix worked better?","How do you know? Use both columns."],key:["the rack with a slot for each paddle","No paddles went in the water and none were damp in the morning, while the rail let 1 paddle in and left 7 damp. Both columns have to be used, not just the paddles in the water."]}]},{id:24,title:"Getting to the Lake, Then and Now",short:"Long Ago",parts:[{std:["HSS-2.1"],n:3,dur:75,dir:"Read the four lines. Answer out loud.",desc:"telling things that happened long ago from things that happened in the last day or two",html:()=>`<p class="big">Four lines from the board in the camp dining hall.</p>
     <table class="bigTable"><tr><th>Line</th><th>What it says</th></tr>
     <tr><td>1</td><td>Yesterday the campers carried four canoes over the portage trail.</td></tr>
     <tr><td>2</td><td>A hundred years ago, visitors reached this lake on a steam boat that came once a week.</td></tr>
     <tr><td>3</td><td>This morning the camp cook got a delivery by road.</td></tr>
     <tr><td>4</td><td>Long before any road came through, the only way in or out of here was by water or on foot.</td></tr></table>`,qs:["Which two lines tell about things that happened long ago?","Which two tell about things that happened in the last day or two?","Pick one of the long ago lines and say what is different about the way it is done now."],key:["Lines 2 and 4, the weekly steam boat and the only way in being by water or on foot.","Lines 1 and 3, carrying the canoes yesterday and the delivery this morning.","Either one: visitors drive in on a road any day instead of waiting for a boat once a week; supplies come by truck instead of only by water or on somebody's back."]}]},{id:25,title:"Where Things Are at Camp",short:"Camp Map",parts:[{std:["HSS-2.2"],n:4,dur:90,dir:"Look at the map. Answer out loud.",desc:"giving an exact place on a map with a letter and a number, and using north, south, east, west and between",html:()=>`<p class="big">The camp, drawn in nine squares. North is at the top.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("pine",46)} pine ridge</td><td>${ic("cabin",46)} cabins</td><td>${ic("mountain",46)} lookout</td></tr>
     <tr><th>B</th><td>${ic("box",46)} camp store</td><td>${ic("fire",46)} fire circle</td><td>${ic("soup",46)} dining hall</td></tr>
     <tr><th>C</th><td>${ic("canoe",46)} canoe racks</td><td>${ic("anchor",46)} the dock</td><td>${ic("wave",46)} swim bay</td></tr></table>
     <p class="big">${ic("compass",56)} North is up, south is down, east is to the right, west is to the left.</p>`,qs:["Give the exact square the fire circle is in, using its letter and number.","What is directly south of the fire circle?","Is the camp store east or west of the dining hall?","Which square is between the canoe racks and the swim bay?"],key:["B2","the dock, in square C2","west. The camp store is in B1 and the dining hall is in B3, so the store is to the left, which is west.","C2, the dock"]}]},{id:26,title:"Rules, Money and the Camp Store",short:"Rules and Money",parts:[{std:["HSS-2.3"],n:3,dur:75,dir:"Answer out loud.",desc:"telling what governments do here, and how another country chooses a leader differently",html:()=>`<p class="big">This lake is inside a state park, so some of the rules here are made by a government and not by the camp.</p>
     <div class="figure">${ic("flag",80)}${ic("board",80)}</div>`,qs:["A park ranger works for the government. Name one thing a ranger does for the people who come here.","Who makes the laws for a whole state? The people the state votes for, or the camp director?","In some other countries the leader is a king or a queen who was born into the job. In our country, how do we get our leaders?"],key:["Any real answer: looks after the trails, keeps the water and the woods healthy, tells people the rules, helps someone who is lost, checks that nobody is harming the park.","the people the state votes for. Accept: the state lawmakers, the legislature, with the governor leading the state.","We vote for them. Any answer that says the people choose their leaders by voting counts."]},{std:["HSS-2.4"],n:3,dur:90,dir:"Read the price list. Answer out loud.",desc:"telling goods from services, spending a set amount, and naming a producer and a consumer",html:()=>`<p class="big">The camp store price list.</p>
     <table class="bigTable"><tr><th>What is on offer</th><th>Price</th></tr>
     <tr><td>a bundle of firewood</td><td>50 cents</td></tr>
     <tr><td>a box of fish hooks</td><td>35 cents</td></tr>
     <tr><td>a map of the trails</td><td>20 cents</td></tr>
     <tr><td>someone to guide you over the portage</td><td>45 cents</td></tr></table>
     <div class="figure">${ic("box",72)}${ic("map",72)}</div>
     <p class="big">This summer was dry, so the camp was told not to cut live trees. There is only as much firewood as the fallen branches give, which is about half as much as last year.</p>`,qs:["Three things on this list are goods and one is a service. Which one is the service, and how do you know?","You have 60 cents. Name two things you could buy with it, and say what you give up.","The camp has only about half the firewood it had last year. Name one thing that does to what the camp can sell, and one thing it does to what campers can buy and use."],key:["Someone guiding you over the portage. It is work somebody does for you, not a thing you carry away.","Any pair at 60 cents or less: hooks and a map is 55 cents, two maps is 40 cents, firewood and a map is 70 cents and is too much. The giving up is the part to listen for.","What the camp can sell: it can make fewer bundles, so it may run out, sell less, charge more, or limit each camper to one. What campers can buy and use: some campers will not get any, each one gets less, they pay more, or they burn smaller fires and use the wood more carefully. Both halves are what is being checked, since this standard is about a limit on a resource changing what is produced and what is used. (HSS-2.4)"]}]},{id:27,title:"Someone Who Made a Difference",short:"Made a Difference",parts:[{std:["HSS-2.5"],n:3,dur:90,dir:"Read about her. Answer out loud.",desc:"telling what one person from the past did, naming a character strength, and saying how it helped others",html:()=>`<p class="passage">Golda Meir was born in Ukraine. She grew up in Milwaukee. That is in the United States. As a schoolgirl she noticed something. Some children could not come to class. Their families could not buy the books. So she booked a hall. She sold tickets. She raised the money. It would pay for their books. She was eleven years old. Later she moved to the country of Israel. She helped build a new town there. She worked her way up. In the end she was chosen as its leader. She was one of the first women to lead. Her country chose her. She was among the first anywhere in the world. She spent years meeting leaders. They came from other countries. She would try to keep hers at peace.</p>
     <div class="figure">${ic("books",80)}${ic("star",80)}</div>`,qs:["What did Golda Meir do when she was eleven years old?","Which word fits her best from what you read: resourceful, careless, or timid? Say why.","Name one way what she did made a difference to other people."],key:["She booked a hall, sold tickets, and raised money so children whose families could not buy books could come to class.","resourceful. Accept determined with the same reasons. Any reason taken from the text: at eleven she worked out how to raise the money herself, she kept going until she was chosen to lead a country.","Any answer from the text: children got the books they needed and could come to school, she helped build a new town, she showed that a woman could lead a country, she worked to keep her country at peace."]}]}];const LEVELUPS={1:{id:"L1",title:"Level Up: Long Camp Words",std:["RF.3.3"],needs:["RF.2.3"],n:3,dir:"Read each long word out loud.",html:()=>`<div style="text-align:center">${["adventure","directions","impossible"].map(w=>`<p class="huge" style="font-size:clamp(2.4rem,8vw,4.4rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["adventure (ad-ven-ture, with ture saying chur)","directions (di-rec-tions, with tion saying shun)","impossible (im-pos-si-ble, with the prefix im-)"]},2:{id:"L2",title:"Level Up: Show Me the Words",std:["RL.3.1"],needs:["RL.2.1"],n:2,dir:"Answer out loud. Then read the words from the story that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${PORTAGE}</p><ol class="qlist"><li>How do you know the canoe was heavy for Dalia? Read the part of the story that shows it.</li><li>How do you know the trail surprised her? Read the part that shows your answer.</li></ol>`,key:["Says it was heavy and reads the line about the canoe riding on her shoulders like a heavy wooden hat, or the line about setting it down to catch her breath.","Says the trail was longer than she expected, and reads the line that the trail to the second lake was longer than it had looked on the map."]},3:{id:"L3",title:"Level Up: Two Steps",std:["3.OA.D.8"],needs:["2.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">Each cabin needs 4 paddles. There are 6 cabins. The shed already has 9 paddles on the rack. How many more paddles does the shed need?</p>`,key:["15 more paddles (6 cabins times 4 paddles is 24, then 24 - 9 = 15)"]},5:{id:"L5",title:"Level Up: Prove It",std:["RI.3.1"],needs:["RI.2.1"],n:2,dir:"Answer out loud. Then read the words from the text that show your answer.",html:()=>`<p class="passage" style="font-size:1.35rem;line-height:1.6">${LAYERS}</p><ol class="qlist"><li>How do you know the sun is not what makes the deep water cold? Read the part of the text that shows it.</li><li>How do you know the wind cannot fix the cold layer at the bottom? Read the part that shows your answer.</li></ol>`,key:["Says the sun never reaches down that far, and reads the sentence that says how few feet of water the sun warms.","Reads the sentence about what the wind does to the top layer, which says plainly how far the stirring gets."]},10:{id:"L10",title:"Level Up: How Long Did It Take",std:["3.MD.A.1"],needs:["2.MD.C.7"],n:2,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The wood crew started splitting at 9:40 a.m. and stopped at 10:25 a.m.</p><ol class="qlist"><li>How many minutes did the work take?</li><li>The next day they started at 3:50 p.m. and worked for 55 minutes. What time did they finish?</li></ol>`,key:["45 minutes (9:40 to 10:00 is 20 minutes, then 10:00 to 10:25 is 25 more)","4:45 p.m. (3:50 plus 10 minutes is 4:00, plus 45 more is 4:45)"]}};const PASSAGE_STD=["RL.2.1","RL.2.2","RI.2.1","RL.3.1","RI.3.1","2-LS2-1","2-LS2-2","2-LS4-1","2-ESS1-1","2-ESS2-1","2-ESS2-2","2-ESS2-3","2-PS1-1","2-PS1-2","2-PS1-3","2-PS1-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-2.1","HSS-2.2","HSS-2.3","HSS-2.4","HSS-2.5"];let chartOn={},pvVal=["",""],blk=[0,0,0];function chartHtml(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${chartOn[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}function pvTable(){let h=`<tr><th>Hundreds</th><th>Tens</th><th>Ones</th></tr>`;pvVal.forEach((v,r)=>{if(r&&!v)return;h+="<tr>";for(let i=0;i<3;i++){const k=v.length-(3-i);h+=`<td>${k>=0?v[k]:""}</td>`}h+="</tr>"});return h}function pvHtml(){const inp=(i,t)=>`<label class="pv-in">${t}<input type="text" inputmode="numeric" maxlength="3" data-pv="${i}" value="${pvVal[i]}" autocomplete="off"></label>`;return inp(0,"Type a number")+inp(1,"Second number (if you need one)")+`<div class="tool-scroll"><table class="pv" id="pvTable">${pvTable()}</table></div><p class="small">Type a number up to 999. Each digit goes in its place.</p>`}function matSvg(h,t,o){return F.blocks(h,t,o)}function blkHtml(){const b=(k,t)=>`<button class="chip" data-b="${k}">${t}</button>`;return`<div class="blk-row">${b("h+","Add a hundred")}${b("h-","Take a hundred")}${b("t+","Add a ten")}${b("t-","Take a ten")}${b("o+","Add a one")}${b("o-","Take a one")}</div><div class="blk-row">${b("to","Trade 10 ones for a ten")}${b("th","Trade 10 tens for a hundred")}${b("bt","Break a ten into ones")}${b("bh","Break a hundred into tens")}${b("x","Clear")}</div><div class="tool-scroll" style="text-align:center">${blk[0]+blk[1]+blk[2]?matSvg(blk[0],blk[1],blk[2]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${blk[0]} hundreds, ${blk[1]} tens, and ${blk[2]} ones on the mat.</p>`}function blkDo(k){const MAX=[9,19,19],i={h:0,t:1,o:2}[k[0]];if(k==="x")blk=[0,0,0];else if(k==="to"){if(blk[2]>=10&&blk[1]<19){blk[2]-=10;blk[1]++}}else if(k==="th"){if(blk[1]>=10&&blk[0]<9){blk[1]-=10;blk[0]++}}else if(k==="bt"){if(blk[1]>=1&&blk[2]<=9){blk[1]--;blk[2]+=10}}else if(k==="bh"){if(blk[0]>=1&&blk[1]<=9){blk[0]--;blk[1]+=10}}else blk[i]=Math.max(0,Math.min(MAX[i],blk[i]+(k[1]==="+"?1:-1)))}const STARTERS={"W.2.1":["I think ____.","One reason is ____.","Another reason is ____.","That is why ____."],"W.2.2":["My topic is ____.","One thing to know is ____.","You also need to ____.","Now you know ____."],"W.2.3":["Early one morning, ____.","First, ____.","Then, ____.","In the end, ____."],"W.2.8":["The log says ____.","On Monday the crew split ____.","The most logs were split on ____.","I remember ____."]};function sentHtml(st){const k=st&&st.parts&&st.parts[0]&&st.parts[0].std&&st.parts[0].std[0]||"W.2.3";return`<ul class="starters">${(STARTERS[k]||STARTERS["W.2.3"]).map(x=>`<li>${x}</li>`).join("")}</ul>`}let tpsNlStart="",tpsNlHops=[],tpsNlShown={};function tpsNlSvg(){if(tpsNlStart==="")return`<p class="small">Type the number to start at.</p>`;const vals=[+tpsNlStart];tpsNlHops.forEach(d=>vals.push(vals[vals.length-1]+d));const uniq=[...new Set(vals)].sort((a,b)=>a-b),gap=72,W=Math.max(320,50+(uniq.length-1)*gap+50),X=v=>50+uniq.indexOf(v)*gap,y=150;let s=`<svg viewBox="0 0 ${W} 200" width="${W}" role="img" aria-label="Open number line">`;s+=`<line x1="16" y1="${y}" x2="${W-16}" y2="${y}" stroke="var(--ink)" stroke-width="3"/><path d="M16 ${y} l9 -6 v12 Z M${W-16} ${y} l-9 -6 v12 Z" fill="var(--ink)"/>`;tpsNlHops.forEach((d,i)=>{const a=X(vals[i]),b=X(vals[i+1]),span=Math.abs(b-a)/gap,top=y-Math.min(120,34+span*26);s+=`<path d="M${a} ${y-10} Q${(a+b)/2} ${2*top-(y-10)} ${b} ${y-10}" fill="none" stroke="var(--sea)" stroke-width="3"/>`;s+=`<text x="${(a+b)/2}" y="${top-6}" font-size="18" font-weight="700" text-anchor="middle" fill="var(--sea)">${d>0?"+":"−"}${Math.abs(d)}</text>`});uniq.forEach(v=>{const x=X(v),open=v===+tpsNlStart||tpsNlShown[v];s+=`<line x1="${x}" y1="${y-10}" x2="${x}" y2="${y+10}" stroke="var(--ink)" stroke-width="3"/>`;s+=`<g ${v===+tpsNlStart?"":`data-tv="${v}" style="cursor:pointer"`}><rect x="${x-27}" y="${y+16}" width="54" height="30" rx="8" fill="${open?"var(--surface)":"var(--sea-soft)"}" stroke="var(--sea)" stroke-width="2" ${open?"":`stroke-dasharray="4 4"`}/><text x="${x}" y="${y+32}" font-size="19" font-weight="700" text-anchor="middle" dominant-baseline="central" fill="var(--ink)">${open?v:"?"}</text></g>`});return s+"</svg>"}function tpsNlHtml(){const j=d=>`<button class="chip" data-tj="${d}">${d>0?"+":"−"}${Math.abs(d)}</button>`;return`<label class="pv-in">Start at<input type="text" inputmode="numeric" maxlength="3" id="tpsNlStart" value="${tpsNlStart}" autocomplete="off"></label><div class="blk-row">${[100,10,5,1].map(j).join("")}</div><div class="blk-row">${[-100,-10,-5,-1].map(j).join("")}<button class="chip" data-tj="u">Undo</button><button class="chip" data-tj="x">Clear</button></div><div class="tool-scroll" id="tpsNlBox" style="text-align:center">${tpsNlSvg()}</div><p class="small">Click a jump the student says. Each landing spot shows a ? until you click it. Click it after the student says the number.</p>`}function tpsNlBind(b,r){const box=()=>b.querySelectorAll("[data-tv]").forEach(g=>g.onclick=()=>{tpsNlShown[g.dataset.tv]=!tpsNlShown[g.dataset.tv];r()});const inp=b.querySelector("#tpsNlStart");inp.oninput=()=>{tpsNlStart=inp.value.replace(/[^0-9]/g,"");tpsNlShown={};b.querySelector("#tpsNlBox").innerHTML=tpsNlSvg();box()};b.querySelectorAll("[data-tj]").forEach(x=>x.onclick=()=>{const k=x.dataset.tj;if(k==="x"){tpsNlHops=[];tpsNlShown={}}else if(k==="u")tpsNlHops.pop();else if(tpsNlStart!==""&&tpsNlHops.length<10)tpsNlHops.push(+k);r()});box()}function tpsCoinHtml(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;align-items:flex-end">${[["Q","25¢"],["D","10¢"],["N","5¢"],["P","1¢"]].map(([k,v])=>`<span style="display:inline-flex;flex-direction:column;align-items:center;gap:4px">${F.coin(k)}<b style="font-size:1.1rem">${v}</b></span>`).join("")}</div><p class="small" style="margin:8px 0 0">This chart gives the value of each coin. The student still does the adding and still writes the cent sign.</p>`}function tpsClockHtml(){return F.row([F.clock(8,50,170),"8:50"],[F.clock(2,15,170),"2:15, quarter past two"])+F.table(["Long hand points at","Minutes","How to say it"],[["12","00","o'clock"],["1","05","five past"],["2","10","ten past"],["3","15","quarter past"],["6","30","half past"],["9","45","quarter to the next hour"]])+`<ul class="frames"><li>Count by fives around the dial. Each numeral the long hand passes is five more minutes.</li><li>The short hand is the hour. When it sits between two numerals, say the smaller one.</li><li>a.m. is before noon. p.m. is after noon.</li></ul>`}function tpsRulerHtml(){return `<div style="text-align:center"><img alt="An inch ruler from 0 to 6 with a pencil lined up at 0. The tip of the pencil is at 5 inches." src="data:image/webp;base64,${window.TP_IMG1.wp3.inchruler}" style="width:640px;max-width:100%;height:auto"></div>`+F.table(["Mark on the ruler","How to say it"],[["the long numbered mark","a whole inch: 1, 2, 3"],["the short mark halfway between two numbers","a half inch, like 4 1/2"]])+F.table(["To measure","Use"],[["something small, like a crayon","an inch ruler"],["a desk or a door","a yardstick or a meter stick"],["something round or bendy, like a wrist","a measuring tape"]])+`<p class="small">Line the left end of the object up with the 0, then read the mark the right end lands on. Write the number with its unit.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["silent e","the e makes the vowel say its name","froze, these, bike"],["ai, ea, ee, oa, ow, oo, ew, ou","a vowel team or a diphthong","tail, seal, boat, book, flew, crowd"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, north, fur"],["un-, re-, pre-","a prefix on the front","unpack, reread, preheat"],["-y, -ly, -ful, -er, -ed, -ing","a suffix on the end","windy, slowly, helpful, jumped"],["two syllables","split the word between its parts","camp / site, sun / set"],["thought, could, through","an irregular spelling","read these as whole words"]])+`<p class="chart-note">Cover the prefix and the suffix, read the middle, then put the word back together.</p>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","the beginning: who it is about and where","First, ____."],["2. Next","the middle: what happened, in order","Next, ____."],["3. Last","the end: how it turned out","Last, ____."],["4. Lesson","what the story teaches","The story teaches ____."]])+`<ul class="frames"><li>Add a fact that fits: where, when, who or what.</li><li>Add a describing detail: how it looked, felt or sounded.</li><li>Speak in whole sentences.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={chart:{name:"120 chart",std:["2.MD.C.8","2.MD.D.10","2.NBT.A.2","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4","3.MD.A.1","3.MD.B.3","3.OA.D.8"],html:chartHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{chartOn[x.dataset.n]=!chartOn[x.dataset.n];r()})},pv:{name:"Place value chart",std:["2.MD.C.8","2.NBT.A.1","2.NBT.A.2","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.4","3.OA.A.1"],html:pvHtml,bind:b=>b.querySelectorAll("[data-pv]").forEach(x=>x.oninput=()=>{pvVal[+x.dataset.pv]=x.value=x.value.replace(/[^0-9]/g,"");b.querySelector("#pvTable").innerHTML=pvTable()})},blocks:{name:"Hundreds, tens, and ones blocks",std:["2.NBT.A.1","2.NBT.A.3","2.NBT.B.7","2.OA.A.1","2.OA.C.3","2.OA.C.4"],html:blkHtml,bind:(b,r)=>b.querySelectorAll("[data-b]").forEach(x=>x.onclick=()=>{blkDo(x.dataset.b);r()})},sent:{name:"Sentence starters",std:["W.2.1","W.2.2","W.2.3","W.2.8"],html:sentHtml},nl:{name:"Open number line",std:["2.NBT.B.7","2.OA.A.1","3.OA.D.8"],html:tpsNlHtml,bind:tpsNlBind},coins:{name:"Coin values",std:["2.MD.C.8"],html:tpsCoinHtml},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.2.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.2.2","SL.2.4","W.2.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","RI.2.1","RL.2.1"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.2.3","RF.2.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"chart",std:["2.NBT.A.2"],msg:"The 120 chart shows the counting sequence, so counting and skip-counting done with it is supported, not independent."},{t:"chart",std:["2.OA.A.1"],msg:"With the 120 chart the student can count on or back square by square. Note it if the answer came from counting by ones."},{t:"chart",std:["2.OA.C.3"],msg:"On the 120 chart the even numbers line up in columns, so odd and even can be read off the chart instead of reasoned out. Note it."},{t:"pv",std:["2.NBT.A.1","2.NBT.A.3"],msg:"The place value chart sorts the digits into hundreds, tens, and ones for the student, so count those items as supported, not independent."},{t:"pv",std:["2.NBT.B.7"],msg:"The place value chart lines the digits up by place, which is most of the work in a written method. Note it."},{t:"blocks",std:["2.NBT.B.7","2.NBT.A.1"],msg:"If you built the numbers with blocks for the student, the item shows they can trade with a model, not that they can use a written method on their own."},{t:"sent",msg:"Sentence starters supply the opening, the reasons and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["L.2.2"],msg:"Write It Right checks capitals, marks, and spelling, so the student has to do the writing. If an adult wrote, do not rate L.2.2 from this stop."},{t:"clock",std:["2.MD.C.7","1.MD.B.3"],msg:"The clock card gives the five minute count around the dial and the a.m. and p.m. rule, so a time read with it open is supported, not independent."},{t:"ruler",std:["2.MD.A.1"],msg:"The ruler card names the inch and half inch marks and which tool to pick, so count a measurement made with it open as supported, not independent."},{t:"letters",std:["RF.2.3"],msg:"The letter and sound card lists the patterns, the prefixes and the suffixes with example words, so a word sounded out with it open is supported, not independent."},{t:"retell",std:["RL.2.2","SL.2.4","W.2.3"],msg:"The card gives the beginning, middle, end frame and asks for the lesson, so count the structure as supported and rate the content the student supplies."},{t:"qwords",std:["RL.2.1","RI.2.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.2.4","RF.2.3"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
